sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
  if (isLoading || newValue === '') {
    return;
  }

  var startDate = '2025-01-14';//g_form.getValue('start_date');
  var endDate = '2025-01-27'; //g_form.getValue('end_date');



  var ga = new GlideAjax('GlideDateTimeUtils'); 
  ga.addParam('sysparm_name', 'getDateTimeDiff'); 
  ga.addParam('sysparm_start', startDate); 
  ga.addParam('sysparm_end', endDate); 
  ga.getXML(getDuration);

  function getDuration(response) {
    var answer = response.responseXML.documentElement.getAttribute("answer");
    g_form.setValue('duration', answer); 
  }
}
